from claude_agent_sdk import ClaudeAgentOptions

async def can_use_tool(tool_name: str, tool_input: dict, ctx) -> dict:
    if tool_name == "Bash" and "git push" in tool_input.get("command", ""):
        return {"behavior": "deny", "message": "Pushes go through the release pipeline."}
    if tool_name == "Write" and tool_input["file_path"].startswith("/etc"):
        return {"behavior": "deny", "message": "System paths are out of scope."}
    return {"behavior": "allow", "updatedInput": tool_input}

options = ClaudeAgentOptions(can_use_tool=can_use_tool)
